  return `<section class="card pending-card"><div class="section-head"><h3>记忆更新</h3>${tag(fmt(item.created_at))}</div><p class="muted">${esc(item.person_name||p.person?.display_name||'人物档案')} · ${esc(item.reason||'沟通结果中的记忆更新')}</p><div class="pending-detail"><strong>${esc(p.kind==='field'?fieldLabel(p.field||'档案信息'):'关系记忆')}</strong><p>${esc(p.content||p.value||p.text||'待审阅提案')}</p>${p.evidence?`<p class="muted">原文：${esc(p.evidence)}</p>`:''}</div><div class="pending-actions">${id?btn('审阅记忆更新','memory-review',`data-id="${esc(id)}"`,'primary'):p.followup_id?btn('打开跟进审阅','followup-detail',`data-id="${esc(p.followup_id)}"`,'primary'):'<p class="followup-error">提案索引缺失，请刷新待确认清单。</p>'}</div></section>`;
