  'apply-followup-seed':d=>{if(state.followupSeed?.id!==d.id||!$('#followup-goal'))return;$('#followup-goal').value=state.followupSeed.goal;followupCache('goal-'+d.id,{goal:state.followupSeed.goal});$('#overlay .followup-goal-suggestion')?.remove();$('#followup-goal').focus();},
  'cancel-chat':async()=>{const s=currentStream();if(s){await api(`/tasks/${s.task.id}/cancel`,{});toast('已请求取消，会在当前步骤结束后停止');}},
  'choose-file':()=>$('#global-file').click(), 'capture-url':async()=>{const url=$('#capture-url').value.trim();if(!url)throw new Error('请输入网页地址');const t=await api('/tasks/url',{url});close();watch(t);await go('tasks');},
  person:d=>personDetail(d.id), 'toggle-archive':()=>{state.archived=!state.archived;return persons();},
