  'archive-person':async d=>{await api(`/persons/${d.id}`,null,'DELETE');close();await persons();toast('人物已归档，可以恢复');},
  'purge-person':async d=>{if(!confirm('彻底清除该人物的结构化档案、账目、记忆及独占附件？此操作不能撤销。共享原文或对话仍可能保留相关内容。'))return;await api(`/persons/${d.id}/purge`,{});close();await persons();toast('关联数据已清除');},
  'edit-field':d=>modal(d.field?'修改档案信息':'补充档案信息',`<div class="form-field"><label>信息类型</label><select id="field-key">${Object.entries({...fieldNames,...(d.field&&!fieldNames[d.field]?{[d.field]:fieldLabel(d.field)}:{})}).map(([k,v])=>`<option value="${esc(k)}" ${k===d.field?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="form-field"><label>内容</label><input id="field-value" value="${esc(d.field?state.detail.fields[d.field]?.value:'')}"></div><div class="form-field"><label>纠错原因（选填）</label><input id="field-reason"></div><div class="form-actions">${btn('保存','save-field',`data-id="${d.id}"`,'primary')}</div>`),
  'save-field':async d=>{const value=$('#field-value').value.trim(),field=$('#field-key').value;if(!value)throw new Error('请输入内容');await api(`/persons/${d.id}/fields`,{field,value,expected_valid_from:expectedField(field),reason:$('#field-reason').value});await personDetail(d.id);toast('已保存，历史版本可查阅');},
  'correct-field':correctField, 'transfer-field':transferField,
  'delete-field':async d=>{await api(`/persons/${d.id}/fields/correct`,{field:d.field,action:'delete',expected_valid_from:expectedField(d.field),reason:$('#correction-reason').value});await personDetail(d.id);toast('当前字段已删除，可以从历史版本恢复');},
  'save-transfer':async d=>{const target=state.transferTarget;if(!target||target.person.id!==$('#transfer-target').value)throw new Error('正在读取接收档案，请稍后重试');await api(`/persons/${d.id}/fields/correct`,{field:d.field,action:'transfer',expected_valid_from:expectedField(d.field),target_person_id:target.person.id,target_expected_valid_from:target.fields[d.field]?.valid_from??null,replace_target:!!$('#replace-target')?.checked,reason:$('#correction-reason').value});await personDetail(target.person.id);toast('已转移归属，双方历史均已保留');},
  'restore-field':d=>{const r=state.fieldHistory.find(r=>r.field===d.field&&r.valid_from===Number(d.version));if(!r)throw new Error('历史记录已变化，请重新打开档案');modal('恢复历史版本',`<h3>${esc(fieldLabel(d.field))} · ${esc(r.value)}</h3><p class="muted">这会新增当前版本，并保留原始来源。当前内容：${esc(state.detail.fields[d.field]?.value||'无')}</p><div class="form-field"><label>恢复原因（选填）</label><input id="correction-reason"></div><div class="form-actions">${btn('确认恢复','save-restored-field',`data-id="${d.id}" data-field="${esc(d.field)}" data-version="${d.version}"`,'primary')}</div>`);},
  'save-restored-field':async d=>{await api(`/persons/${d.id}/fields/correct`,{field:d.field,action:'restore',version:Number(d.version),expected_valid_from:expectedField(d.field),reason:$('#correction-reason').value});await personDetail(d.id);toast('已恢复为新的当前版本');},
  'toggle-void':()=>{state.showVoid=!state.showVoid;state.ledgerOffset=0;return ledger();},'ledger-detail':d=>ledgerDetail(d.id),
  'ledger-page':d=>{state.ledgerOffset=Math.max(0,Number(d.offset)||0);return ledger();},
  'save-ledger':async d=>{const value=$('#ledger-amount').value.trim();if(!/^\d+(\.\d{1,2})?$/.test(value))throw new Error('请输入正数金额，最多两位小数');const [whole,decimal='']=value.split('.');const amount=Number(whole)*100+Number(decimal.padEnd(2,'0'));if(!Number.isSafeInteger(amount)||amount<=0)throw new Error('金额无效');await api(`/ledger/${d.id}`,{expected_revision:state.ledgerEntry.revision,person_id:$('#ledger-person').value||null,direction:$('#ledger-direction').value,amount_cents:amount,occurred_on:$('#ledger-date').value,note:$('#ledger-note').value,reason:$('#ledger-reason').value},'PATCH');close();await ledger();toast('账目已修改，汇总已更新');},
  'confirm-void-ledger':d=>{state.voidReason=$('#ledger-reason').value;modal('撤销这笔账目',`<p>${esc(snapshotText(state.ledgerEntry))}</p><p class="muted">撤销后不计入收支汇总，原始凭证和修改记录仍可查阅。</p><div class="form-actions">${btn('返回','ledger-detail',`data-id="${d.id}"`)}${btn('确认撤销','void-ledger',`data-id="${d.id}"`,'danger')}</div>`);},
  'void-ledger':async d=>{await api(`/ledger/${d.id}/void`,{expected_revision:state.ledgerEntry.revision,reason:state.voidReason});close();await ledger();toast('账目已撤销，不再计入汇总');},
